// MONTAR RESPOSTA — junta as tabelas todas no formato que a app consome.
const pega = nome => { try { return $(nome).all().map(i => i.json); } catch (e) { return []; } };
const F = r => r.fields || r;
const id = r => r.id || F(r).id || null;
const um = v => Array.isArray(v) ? (v[0] || null) : (v || null);
const txt = (f, ...ks) => { for (const k of ks) if (f[k] !== undefined && f[k] !== null && f[k] !== '') return f[k]; return null; };

const comerciais = pega('Comerciais').map(r => { const f = F(r); return {
  id: id(r), nome: txt(f,'Nome','nome'), email: txt(f,'Email','email'),
  telefone: txt(f,'Telefone','telefone'), ativo: f.Ativo !== false }; }).filter(c => c.nome);

const leads = pega('Leads').map(r => { const f = F(r); return {
  id: id(r), nome: txt(f,'Nome','nome'),
  comercial_id: um(f.Comercial || f.Comerciais || f.comercial),
  estagio: txt(f,'estagio','Estagio','Estágio') || 'lead',
  status: txt(f,'Status','status'),
  valor: f.Valor || f.valor || null,
  telefone: txt(f,'Telefone','telefone'),
  email: txt(f,'Email','email'),
  origem_lead: txt(f,'origem_lead','Origem'),
  tipo: txt(f,'tipo','Tipo'),
  ultima_nota: txt(f,'ultima_nota','Ultima_nota'),
  ultimo_contacto: txt(f,'ultimo_contacto','Ultimo_contacto','data_dita'),
  banco_origem: txt(f,'banco_origem'),
  motivo_saida: txt(f,'motivo_saida'),
  checklist_documentos: (() => { const v=f.checklist_documentos; if(!v) return null; if(typeof v==='string'){ try{ return JSON.parse(v); }catch(e){ return null; } } return v; })(),
  propostas_banco: (() => { const v=f.propostas_banco; if(!v) return null; if(typeof v==='string'){ try{ return JSON.parse(v); }catch(e){ return null; } } return v; })()
}; }).filter(l => l.nome);

const tarefas = pega('Tarefas').map(r => { const f = F(r); return {
  id: id(r), tarefa: txt(f,'tarefa','Tarefa'), lead_id: um(f.Lead || f.Leads),
  evento_id: um(f.Eventos || f.Evento), prazo: txt(f,'prazo','Prazo'),
  estado: txt(f,'estado','Estado') || 'aberta',
  follow_up_auto: !!f.follow_up_auto, follow_up_prazo: txt(f,'follow_up_prazo') }; }).filter(t => t.tarefa);

const agenda = pega('Agenda').map(r => { const f = F(r); return {
  id: id(r), titulo: txt(f,'titulo','Titulo'), lead_id: um(f.Lead || f.Leads),
  evento_id: um(f.Evento || f.Eventos), quando: txt(f,'quando','Quando'),
  estado: txt(f,'estado','Estado') || 'agendado' }; }).filter(a => a.titulo);

const pendencias = pega('Pendencias').map(r => { const f = F(r); return {
  id: id(r), descricao: txt(f,'descricao','Descricao'), lead_id: um(f.Lead || f.Leads),
  evento_id: um(f.Evento || f.Eventos), depende_de: txt(f,'depende_de'),
  data_prometida: txt(f,'data_prometida'), origem: txt(f,'origem'),
  estado: txt(f,'estado','Estado') || 'aberta' }; }).filter(p => p.descricao);

const historico = pega('Historico').map(r => { const f = F(r); return {
  id: id(r), registo: txt(f,'Registo','registo'), tipo_registo: txt(f,'tipo_registo'),
  nota: txt(f,'nota','Nota'), lead_id: um(f.Lead || f.Leads),
  evento_id: um(f.Eventos || f.Evento), data: txt(f,'Data','data'),
  desfecho: txt(f,'desfecho') }; });

const config = {};
for (const r of pega('Config')) {
  const f = F(r);
  const k = txt(f,'chave','Chave','key','Nome','nome');
  let v = f.valor !== undefined ? f.valor : (f.Valor !== undefined ? f.Valor : f.value);
  if (!k) continue;
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) {} }
  config[String(k).trim().toLowerCase()] = v;
}
const seq = config['sequencia_estagios'];
config.estagios = (seq && seq.ordem) || (Array.isArray(seq) ? seq : null) ||
  ['lead','aguarda_documentos','aguarda_decisao_banco','aprovado','proposta_enviada',
   'aguarda_banco','escritura_marcada','fecho'];

let corpo = {};
try { corpo = $('Webhook').first().json.body || {}; } catch (e) {}
const so = corpo.comercial_id || null;

return [{ json: {
  ok: true,
  gerado_em: new Date().toISOString(),
  comerciais,
  leads: so ? leads.filter(l => !l.comercial_id || l.comercial_id === so) : leads,
  tarefas, agenda, pendencias,
  historico: historico.slice(0, 400),
  config,
} }];
